 const keys=[...listing.matchAll(/<Key>([^<]+)<\/Key>/g)].map(m=>m[1]);out.date_keys=keys.filter(k=>k.includes('2026-10-03'));const zip=out.date_keys.filter(k=>k.startsWith(periodPrefix)&&k.endsWith('.zip'));if(zip.length!==1)throw Error('EXACT_DAY_ARCHIVE_KEY_REQUIRED');const check=zip[0].replace(/\.zip$/,'.CHECKSUM');if(!keys.includes(check))throw Error('EXACT_DAY_CHECKSUM_KEY_REQUIRED');
